mapper.select:
select u.user_id, u.user_name, u.password,u.nick_name, u.email, u.avatar
     , u.phonenumber, u.status,u.pwd_update_time,u.tenant_id,u.user_type
from sys_user u
where u.del_flag = '0' and u.STATUS = '0'

    AND u.user_id IN

        #{item}



    AND u.user_name = #{userName}


    AND u.user_name IN

        #{item}

SELECT task_id, stage_id, event_code, task_name, task_progress, task_start_date, task_stop_date, task_detail, task_status, user_ids, CASE WHEN SUBSTRING(task_name, 1, 1) REGEXP '[一-龥]' THEN firstPinyin(task_name) ELSE SUBSTRING(task_name, 1, 1) END AS task_name_ord FROM vm_emergency_task_t WHERE delete_flag = 0 ${dataScope}
AND stage_id = #{stageId}
AND FIND_IN_SET(#{userId},user_ids)
AND task_name like concat('%',#{taskName},'%')
AND task_start_date >= #{taskStartDateBegin} AND task_start_date <= #{taskStartDateEnd}
AND task_stop_date >= #{taskStopDateBegin} AND task_stop_date <= #{taskStopDateEnd}
AND event_code = #{eventCode}
AND event_code IN
#{item}
AND task_status = #{taskStatus}
AND task_status != 0
order by task_start_date desc, IF(task_name_ord RLIKE '^[a-z]', 1, 2), task_name_ord

SELECT id, task_id, task_progress, feedback_detail, creator, create_time as feedbackTime FROM vm_emergency_feedback_t WHERE delete_flag = 0
AND id = #{id}
AND task_id = #{taskId}
AND task_id IN
#{item}
order by create_time desc

SELECT stage_id, event_code, stage_name, stage_start_date, stage_stop_date, stage_detail, stage_status FROM vm_emergency_stage_t WHERE delete_flag = 0
AND stage_id = #{stageId}
AND event_code = #{eventCode}

SELECT COUNT(*)
FROM vm_emergency_target_t
WHERE event_code = #{eventCode}
  AND delete_flag = 0;
